DROP TABLE IF EXISTS `base_org_resource`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `base_org_resource` (
  `id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '资源id',
  `code` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '资源code',
  `type` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '资源类型',
  `name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '资源名称',
  `url` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '资源url',
  `method` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '资源方法',
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '简介',
  `application` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'legacy' COMMENT '来源应用',
  `product_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'opensabre-admin' COMMENT '归属产品编码，COMMON 表示公共资源',
  `source` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MANUAL' COMMENT '资源来源',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE' COMMENT '注册状态',
  `handler` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '处理器方法',
  `first_seen_at` datetime DEFAULT NULL COMMENT '首次发现时间',
  `last_seen_at` datetime DEFAULT NULL COMMENT '最后发现时间',
  `missing_since` datetime DEFAULT NULL COMMENT '首次缺失时间',
  `app_version` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '应用版本',
  `created_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updated_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `created_by` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建人',
  `updated_by` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '更新人',
  PRIMARY KEY (`id`),
  UNIQUE KEY `ux_resource_code` (`code`),
  KEY `ix_resource_endpoint` (`application`,`method`,`url`),
  KEY `ix_resource_product` (`product_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='资源表';
/*!40101 SET character_set_client = @saved_cs_client */;

